Sak$w=>{
	let dx=w.Sx.p-w.Cx.p;
	let dy=w.Sy.p-w.Cy.p;
	let dz=w.Sz.p-w.Cz.p;
	let dist2=dx*dx+dy*dy+dz*dz;
	let br=w.BoundR.p; //FIXME should this be .R? By BoundR i mean the bounding sphere radius, which the stdDev is less than.
	if(dist2>br*br)return 0;
	let sd=br*(1/3); //stdDev is less than bounding sphere radius
	return w.p*Math.exp(-dist2/(2*sd*sd));
}

